#include <stdio.h>

#define MAX_CATS 5

int line[MAX_CATS];
int head = 0;
int tail = 0;

int is_empty(void) { return head == tail; }
int is_full(void) { return tail == MAX_CATS; }

int enqueue(int value) {
    if (is_full()) {
        return 0;
    }
    line[tail] = value;
    tail++;
    return 1;
}

int dequeue(int *value) {
    if (is_empty()) {
        return 0;
    }
    *value = line[head];
    head++;
    return 1;
}

int main(void) {
    enqueue({a});
    enqueue({b});
    enqueue({c});
    printf("队伍里有 %d 只猫\n", tail - head);

    int v = 0;
    while (dequeue(&v)) {
        printf("领到 %d\n", v);
    }
    printf("队空了吗？%s，可 head 已经走到 %d\n", is_empty() ? "空了" : "还有", head);
    return 0;
}
